CREATE TABLE refund_item_lots(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,refund_item_id BIGINT UNSIGNED NOT NULL,lot_id BIGINT UNSIGNED NOT NULL,quantity_base DECIMAL(18,6) NOT NULL,KEY idx_refund_lots(refund_item_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE refund_item_serials(refund_item_id BIGINT UNSIGNED NOT NULL,serial_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(refund_item_id,serial_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE refund_item_components(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,refund_item_id BIGINT UNSIGNED NOT NULL,component_product_id BIGINT UNSIGNED NOT NULL,component_variant_id BIGINT UNSIGNED NULL,quantity_base DECIMAL(18,6) NOT NULL,PRIMARY KEY(id),KEY idx_refund_components(refund_item_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE sale_voids(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id BIGINT UNSIGNED NOT NULL,branch_id BIGINT UNSIGNED NOT NULL,sale_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,reason VARCHAR(255) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_sale_void(sale_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;